function validateValue<K extends ConfigKey>(key: K, value: unknown): ConfigValueTypes[K] {
    const entry = requireConfigEntry(key)

    if (entry.type === 'boolean') return requireBoolean(value, entry.key) as ConfigValueTypes[K]
