        });
    });

    it('migrates the legacy flat selection without losing active values', () => {
        const store = createFakeStore({
            [DESKTOP_CONFIG_STORE_KEY]: {
                agent: 'claude',
                model: 'opus',
                permissionMode: 'full-access',
                thinkingLevel: 'max',
